{"path":"src/lib/books.ts","content":"import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: 'reading' | 'finished';
  createdAt: string;
  finishedAt: string | null;
};

function booksFile() {
  return join(process.cwd(), 'data', 'books.json');
}

export async function getBooks(): Promise<Book[]> {
  try {
    const contents = await readFile(booksFile(), 'utf8');
    const books: unknown = JSON.parse(contents);
    if (!Array.isArray(books)) throw new Error('The books file must contain an array.');
    return books as Book[];
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(books: Book[]) {
  const file = booksFile();
  await mkdir(dirname(file), { recursive: true });
  const temporaryFile = `${file}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(temporaryFile, file);
  } finally {
    await unlink(temporaryFile).catch((error: NodeJS.ErrnoException) => {
      if (error.code !== 'ENOENT') throw error;
    });
  }
}

// Serialize changes within this server process so simultaneous submissions do not lose books.
let pending: Promise<unknown> = Promise.resolve();

function updateBooks<T>(change: (books: Book[]) => T): Promise<T> {
  const operation = pending.then(async () => {
    const books = await getBooks();
    const result = change(books);
    await saveBooks(books);
    return result;
  });
  pending = operation.catch(() => undefined);
  return operation;
}

export function createBook(input: Pick<Book, 'title' | 'author' | 'notes'>): Promise<Book> {
  return updateBooks((books) => {
    const book: Book = {
      id: randomUUID(),
      ...input,
      status: 'reading',
      createdAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.unshift(book);
    return book;
  });
}

export function finishBook(id: string): Promise<boolean> {
  return updateBooks((books) => {
    const book = books.find((item) => item.id === id);
    if (!book) return false;
    if (book.status !== 'finished') {
      book.status = 'finished';
      book.finishedAt = new Date().toISOString();
    }
    return true;
  });
}
"}

{"path":"src/app/actions.ts","content":"'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { createBook, finishBook } from '../lib/books';

export type AddBookState = { error: string | null };

export async function addBook(
  _previousState: AddBookState,
  formData: FormData,
): Promise<AddBookState> {
  const title = formData.get('title');
  const author = formData.get('author');
  const notes = formData.get('notes');

  if (typeof title !== 'string' || typeof author !== 'string' || typeof notes !== 'string') {
    return { error: 'Please enter a title and author.' };
  }

  const cleanTitle = title.trim();
  const cleanAuthor = author.trim();
  const cleanNotes = notes.trim();
  if (!cleanTitle || !cleanAuthor) {
    return { error: 'Please enter a title and author.' };
  }
  if (cleanTitle.length > 200 || cleanAuthor.length > 200 || cleanNotes.length > 5000) {
    return { error: 'The title, author, or notes are too long.' };
  }

  const book = await createBook({ title: cleanTitle, author: cleanAuthor, notes: cleanNotes });
  revalidatePath('/');
  redirect(`/books/${book.id}`);
}

export async function markFinished(formData: FormData): Promise<void> {
  const id = formData.get('id');
  if (typeof id !== 'string' || !/^[\da-f]{8}-[\da-f-]{27,}$/.test(id)) return;
  if (await finishBook(id)) {
    revalidatePath('/');
    revalidatePath(`/books/${id}`);
  }
}
"}

