import { useState } from 'react';

export function CopyLinkButton() {
  const [message, setMessage] = useState('Copy book link');

  async function copyLink() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setMessage('Link copied!');
    } catch {
      setMessage('Copy the URL from your address bar');
    }
  }

  return <button type="button" className="outline-button" onClick={copyLink}>{message} <span aria-hidden="true">↗</span></button>;
}
"}

