import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { markFinished } from '../../actions';
import { BookCover } from '../../../components/book-cover';
import { CopyLinkButton } from '../../../components/copy-link-button';
import { getBooks } from '../../../lib/books';

type Props = { params: Promise<{ id: string }> };

export const dynamic = 'force-dynamic';

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  const book = (await getBooks()).find((item) => item.id === id);
  return book ? { title: book.title, description: `${book.title} by ${book.author} · Reading Room` } : { title: 'Book not found' };
}

export default async function BookPage({ params }: Props) {
  const { id } = await params;
  const book = (await getBooks()).find((item) => item.id === id);
  if (!book) notFound();

  return (
    <main className="shell detail-page">
      <Link href="/" className="back-link"><span aria-hidden="true">←</span> Back to your books</Link>
      <div className="detail-content">
        <div className="detail-cover-area"><BookCover title={book.title} large /><span className="cover-caption">A STORY ON YOUR SHELF · {book.status === 'reading' ? 'IN PROGRESS' : 'COMPLETED'}</span></div>
        <div className="detail-body">
          <span className="eyebrow"><span className="eyebrow-line" /> {book.status === 'reading' ? 'CURRENTLY READING' : 'FINISHED READING'}</span>
          <h1>{book.title}</h1>
          <p className="detail-author">by {book.author}</p>
          <div className="detail-actions">
            {book.status === 'reading' && (
              <form action={markFinished}>
                <input type="hidden" name="id" value={book.id} />
                <button type="submit" className="primary-button">Mark as finished <span aria-hidden="true">✓</span></button>
